CREATE TABLE public.mastery_identity_settings (sport text PRIMARY KEY CHECK (sport IN ('baseball','softball')), initial_window integer NOT NULL DEFAULT 100 CHECK (initial_window>0), transition_at integer NOT NULL DEFAULT 500 CHECK (transition_at>0), later_window integer NOT NULL DEFAULT 500 CHECK (later_window>0), elite_home_runs integer CHECK (elite_home_runs>=0), lacking_power_home_runs integer CHECK (lacking_power_home_runs>=0), elite_balls_in_play_rate numeric CHECK (elite_balls_in_play_rate BETWEEN 0 AND 1), speed_minimum_samples integer CHECK (speed_minimum_samples>0), pitching_unit text NOT NULL DEFAULT 'batters faced' CHECK (pitching_unit='batters faced'), defense_unit text NOT NULL DEFAULT 'fielding chances' CHECK (defense_unit='fielding chances'), updated_by uuid REFERENCES public.profiles(id), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT valid_mastery_window CHECK (transition_at%initial_window=0), CONSTRAINT valid_power_cutoffs CHECK (elite_home_runs IS NULL OR lacking_power_home_runs IS NULL OR lacking_power_home_runs<elite_home_runs)); GRANT SELECT, INSERT, UPDATE ON public.mastery_identity_settings TO authenticated; GRANT ALL ON public.mastery_identity_settings TO service_role; ALTER TABLE public.mastery_identity_settings ENABLE ROW LEVEL SECURITY; CREATE POLICY mastery_settings_read ON public.mastery_identity_settings FOR SELECT TO authenticated USING (true); CREATE POLICY mastery_settings_owner_insert ON public.mastery_identity_settings FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(),'owner') OR public.has_role(auth.uid(),'admin')); CREATE POLICY mastery_settings_owner_update ON public.mastery_identity_settings FOR UPDATE TO authenticated USING (public.has_role(auth.uid(),'owner') OR public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'owner') OR public.has_role(auth.uid(),'admin')); CREATE TABLE public.mastery_identity_settings_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sport text NOT NULL, actor uuid, changed_at timestamptz NOT NULL DEFAULT now(), previous jsonb, current jsonb NOT NULL); GRANT SELECT ON public.mastery_identity_settings_audit TO authenticated; GRANT ALL ON public.mastery_identity_settings_audit TO service_role; ALTER TABLE public.mastery_identity_settings_audit ENABLE ROW LEVEL SECURITY; CREATE POLICY mastery_settings_audit_owner ON public.mastery_identity_settings_audit FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'owner') OR public.has_role(auth.uid(),'admin')); CREATE FUNCTION public.mastery_settings_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.updated_by:=auth.uid(); NEW.updated_at:=clock_timestamp(); INSERT INTO public.mastery_identity_settings_audit(sport,actor,previous,current) VALUES(NEW.sport,auth.uid(),CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,to_jsonb(NEW)); RETURN NEW; END $$; REVOKE ALL ON FUNCTION public.mastery_settings_audit() FROM PUBLIC; CREATE TRIGGER mastery_settings_change BEFORE INSERT OR UPDATE ON public.mastery_identity_settings FOR EACH ROW EXECUTE FUNCTION public.mastery_settings_audit(); COMMENT ON TABLE public.mastery_identity_settings IS 'Owner policy only. Missing cutoffs remain unknown; not athlete identity storage. Batting AB, pitching BF and defense chances share opportunity cadence.';